function applyDict(dict: Record<string,string>) {
  for (const k in dict) {
    if (dict.hasOwnProperty(k)) tr.dict[k] = dict[k];
  }
  tr.dict["Русский"] = "Русский";
}

function applyCode(code: string) {
  // Set top-level tr properties
  if (code === 'de') {
    tr.Settings = DE.Settings; tr.General = DE.General; tr.Display = DE.Display;
    tr.Sampling = DE.Sampling; tr.Penalties = DE.Penalties; tr.Tools = DE.Tools;
    tr.Agentic = DE.Agentic; tr.Developer = DE.Developer; tr.ImpExp = DE["Import / Export"];
    tr.Language = DE.Language; tr.Theme = DE.Theme; tr.SvrEndpoint = DE["Server Endpoint"];
    tr.WebUiAddr = DE["Web UI Address"]; tr.EnableWebUi = DE["Enable Web UI"];
    tr.ApiKey = DE["API Key"]; tr.SysMsg = DE["System Message"]; tr.NewChat = DE["New Chat"];
    tr.TypeMsg = DE["Type a message..."]; tr.Search = DE.Search; tr.Reload = DE["Reload app"];
    tr.Back = DE["Back to Chat"]; tr.Send = DE.Send; tr.Reset = DE["Reset to default"];
    tr.Save = DE["Save settings"]; tr.ShowStats = DE["Show message generation statistics"];
    tr.Temp = DE.Temperature; tr.TopK = DE["Top K"]; tr.TopP = DE["Top P"];
    tr.MinP = DE["Min P"]; tr.MaxTokens = DE["Max tokens"]; tr.Samplers = DE.Samplers;
  } else if (code === 'ru') {
    tr.Settings = RU.Settings; tr.General = RU.General; tr.Display = RU.Display;
    tr.Sampling = RU.Sampling; tr.Penalties = RU.Penalties; tr.Tools = RU.Tools;
    tr.Agentic = RU.Agentic; tr.Developer = RU.Developer; tr.ImpExp = RU["Import / Export"];
    tr.Language = RU.Language; tr.Theme = RU.Theme; tr.SvrEndpoint = RU["Server Endpoint"];
    tr.WebUiAddr = RU["Web UI Address"]; tr.EnableWebUi = RU["Enable Web UI"];
    tr.ApiKey = RU["API Key"]; tr.SysMsg = RU["System Message"]; tr.NewChat = RU["New Chat"];
    tr.TypeMsg = RU["Type a message..."]; tr.Search = RU.Search; tr.Reload = RU["Reload app"];
    tr.Back = RU["Back to Chat"]; tr.Send = RU.Send; tr.Reset = RU["Reset to default"];
    tr.Save = RU["Save settings"]; tr.ShowStats = RU["Show message generation statistics"];
    tr.Temp = RU.Temperature; tr.TopK = RU["Top K"]; tr.TopP = RU["Top P"];
    tr.MinP = RU["Min P"]; tr.MaxTokens = RU["Max tokens"]; tr.Samplers = RU.Samplers;
  } else if (code === 'es') {
    tr.Settings = ES_FULL.Settings; tr.General = ES_FULL.General; tr.Display = ES_FULL.Display;
    tr.Sampling = ES_FULL.Sampling; tr.Penalties = ES_FULL.Penalties; tr.Tools = ES_FULL.Tools;
    tr.Agentic = ES_FULL.Agentic; tr.Developer = ES_FULL.Developer; tr.ImpExp = ES_FULL["Import / Export"];
    tr.Language = ES_FULL.Language; tr.Theme = ES_FULL.Theme; tr.SvrEndpoint = ES_FULL["Server Endpoint"];
    tr.WebUiAddr = ES_FULL["Web UI Address"]; tr.EnableWebUi = ES_FULL["Enable Web UI"];
    tr.ApiKey = ES_FULL["API Key"]; tr.SysMsg = ES_FULL["System Message"]; tr.NewChat = ES_FULL["New Chat"];
    tr.TypeMsg = ES_FULL["Type a message..."]; tr.Search = ES_FULL.Search; tr.Reload = ES_FULL["Reload app"];
    tr.Back = ES_FULL["Back to Chat"]; tr.Send = ES_FULL.Send; tr.Reset = ES_FULL["Reset to default"];
    tr.Save = ES_FULL["Save settings"]; tr.ShowStats = ES_FULL["Show message generation statistics"];
    tr.Temp = ES_FULL.Temperature; tr.TopK = ES_FULL["Top K"]; tr.TopP = ES_FULL["Top P"];
    tr.MinP = ES_FULL["Min P"]; tr.MaxTokens = ES_FULL["Max tokens"]; tr.Samplers = ES_FULL.Samplers;
  } else if (code === 'fr') {
    tr.Settings = FR_FULL.Settings; tr.General = FR_FULL.General; tr.Display = FR_FULL.Display;
    tr.Sampling = FR_FULL.Sampling; tr.Penalties = FR_FULL.Penalties; tr.Tools = FR_FULL.Tools;
    tr.Agentic = FR_FULL.Agentic; tr.Developer = FR_FULL.Developer; tr.ImpExp = FR_FULL["Import / Export"];
    tr.Language = FR_FULL.Language; tr.Theme = FR_FULL.Theme; tr.SvrEndpoint = FR_FULL["Server Endpoint"];
    tr.WebUiAddr = FR_FULL["Web UI Address"]; tr.EnableWebUi = FR_FULL["Enable Web UI"];
    tr.ApiKey = FR_FULL["API Key"]; tr.SysMsg = FR_FULL["System Message"]; tr.NewChat = FR_FULL["New Chat"];
    tr.TypeMsg = FR_FULL["Type a message..."]; tr.Search = FR_FULL.Search; tr.Reload = FR_FULL["Reload app"];
    tr.Back = FR_FULL["Back to Chat"]; tr.Send = FR_FULL.Send; tr.Reset = FR_FULL["Reset to default"];
    tr.Save = FR_FULL["Save settings"]; tr.ShowStats = FR_FULL["Show message generation statistics"];
    tr.Temp = FR_FULL.Temperature; tr.TopK = FR_FULL["Top K"]; tr.TopP = FR_FULL["Top P"];
    tr.MinP = FR_FULL["Min P"]; tr.MaxTokens = FR_FULL["Max tokens"]; tr.Samplers = FR_FULL.Samplers;
  } else {
    tr.Settings = 'Settings'; tr.General = 'General'; tr.Display = 'Display';
    tr.Sampling = 'Sampling'; tr.Penalties = 'Penalties'; tr.Tools = 'Tools';
    tr.Agentic = 'Agentic'; tr.Developer = 'Developer'; tr.ImpExp = 'Import / Export';
    tr.Language = 'Language'; tr.Theme = 'Theme'; tr.SvrEndpoint = 'Server Endpoint';
    tr.WebUiAddr = 'Web UI Address'; tr.EnableWebUi = 'Enable Web UI';
    tr.ApiKey = 'API Key'; tr.SysMsg = 'System Message'; tr.NewChat = 'New Chat';
    tr.TypeMsg = 'Type a message...'; tr.Search = 'Search'; tr.Reload = 'Reload app';
    tr.Back = 'Back to Chat'; tr.Send = 'Send'; tr.Reset = 'Reset to default';
    tr.Save = 'Save settings'; tr.ShowStats = 'Show message generation statistics';
    tr.Temp = 'Temperature'; tr.TopK = 'Top K'; tr.TopP = 'Top P';
    tr.MinP = 'Min P'; tr.MaxTokens = 'Max tokens'; tr.Samplers = 'Samplers';
  }

  // Full dict entries
  if (code === 'es') {
    applyDict(ES_FULL);
  } else if (code === 'fr') {
    applyDict(FR_FULL);
  } else {
    // Dict entries for help text and dynamic strings — loaded from /lang/{code}.json at runtime
    if (browser) {
      fetch('/lang/' + code + '.json')
        .then(r => r.json())
        .then(d => applyDict(d))
        .catch(() => {});
    }

    // Immediate dict entries for static strings (de/ru/en)
    tr.dict["Import / Export"] = code === 'ru' ? RU["Import / Export"] : code === 'de' ? DE["Import / Export"] : 'Import / Export';
    tr.dict["Server Endpoint"] = code === 'ru' ? RU["Server Endpoint"] : code === 'de' ? DE["Server Endpoint"] : 'Server Endpoint';
    tr.dict["Web UI Address"] = code === 'ru' ? RU["Web UI Address"] : code === 'de' ? DE["Web UI Address"] : 'Web UI Address';
    tr.dict["Enable Web UI"] = code === 'ru' ? RU["Enable Web UI"] : code === 'de' ? DE["Enable Web UI"] : 'Enable Web UI';
    tr.dict["API Key"] = code === 'ru' ? RU["API Key"] : code === 'de' ? DE["API Key"] : 'API Key';
    tr.dict["System Message"] = code === 'ru' ? RU["System Message"] : code === 'de' ? DE["System Message"] : 'System Message';
    tr.dict["New Chat"] = code === 'ru' ? RU["New Chat"] : code === 'de' ? DE["New Chat"] : 'New Chat';
    tr.dict["Type a message..."] = code === 'ru' ? RU["Type a message..."] : code === 'de' ? DE["Type a message..."] : 'Type a message...';
    tr.dict["Reload app"] = code === 'ru' ? RU["Reload app"] : code === 'de' ? DE["Reload app"] : 'Reload app';
    tr.dict["Back to Chat"] = code === 'ru' ? RU["Back to Chat"] : code === 'de' ? DE["Back to Chat"] : 'Back to Chat';
    tr.dict["Reset to default"] = code === 'ru' ? RU["Reset to default"] : code === 'de' ? DE["Reset to default"] : 'Reset to default';
    tr.dict["Save settings"] = code === 'ru' ? RU["Save settings"] : code === 'de' ? DE["Save settings"] : 'Save settings';
    tr.dict["Show message generation statistics"] = code === 'ru' ? RU["Show message generation statistics"] : code === 'de' ? DE["Show message generation statistics"] : 'Show message generation statistics';
    tr.dict["Top K"] = code === 'ru' ? RU["Top K"] : code === 'de' ? DE["Top K"] : 'Top K';
    tr.dict["Top P"] = code === 'ru' ? RU["Top P"] : code === 'de' ? DE["Top P"] : 'Top P';
    tr.dict["Min P"] = code === 'ru' ? RU["Min P"] : code === 'de' ? DE["Min P"] : 'Min P';
    tr.dict["Max tokens"] = code === 'ru' ? RU["Max tokens"] : code === 'de' ? DE["Max tokens"] : 'Max tokens';
    tr.dict["Settings"] = code === 'ru' ? RU.Settings : code === 'de' ? DE.Settings : 'Settings';
    tr.dict["General"] = code === 'ru' ? RU.General : code === 'de' ? DE.General : 'General';
    tr.dict["Display"] = code === 'ru' ? RU.Display : code === 'de' ? DE.Display : 'Display';
    tr.dict["Sampling"] = code === 'ru' ? RU.Sampling : code === 'de' ? DE.Sampling : 'Sampling';
    tr.dict["Penalties"] = code === 'ru' ? RU.Penalties : code === 'de' ? DE.Penalties : 'Penalties';
    tr.dict["Tools"] = code === 'ru' ? RU.Tools : code === 'de' ? DE.Tools : 'Tools';
    tr.dict["Agentic"] = code === 'ru' ? RU.Agentic : code === 'de' ? DE.Agentic : 'Agentic';
    tr.dict["Developer"] = code === 'ru' ? RU.Developer : code === 'de' ? DE.Developer : 'Developer';
    tr.dict["Language"] = code === 'ru' ? RU.Language : code === 'de' ? DE.Language : 'Language';
    tr.dict["Theme"] = code === 'ru' ? RU.Theme : code === 'de' ? DE.Theme : 'Theme';
    tr.dict["Search"] = code === 'ru' ? RU.Search : code === 'de' ? DE.Search : 'Search';
    tr.dict["Send"] = code === 'ru' ? RU.Send : code === 'de' ? DE.Send : 'Send';
    tr.dict["Temperature"] = code === 'ru' ? RU.Temperature : code === 'de' ? DE.Temperature : 'Temperature';
    tr.dict["Samplers"] = code === 'ru' ? RU.Samplers : code === 'de' ? DE.Samplers : 'Samplers';
    tr.dict["English"] = code === 'ru' ? RU.English : code === 'de' ? DE.English : 'English';
    tr.dict["Deutsch"] = code === 'ru' ? RU.Deutsch : code === 'de' ? DE.Deutsch : 'Deutsch';
    tr.dict["Hello there"] = code === 'ru' ? "Здравствуйте" : code === 'de' ? "Hallo" : "Hello there";
    tr.dict["Hello there!"] = code === 'ru' ? "Здравствуйте!" : code === 'de' ? "Hallo!" : "Hello there!";
    tr.dict["Type a message or upload a file to get started"] = code === 'ru' ? "Введите сообщение или загрузите файл" : code === 'de' ? "Nachricht eingeben oder Datei hochladen" : "Type a message or upload a file to get started";
    tr.dict["Search conversations..."] = code === 'ru' ? "Поиск по беседам..." : code === 'de' ? "Unterhaltungen suchen..." : "Search conversations...";
  }
}

if (browser) {
  const saved = (localStorage.getItem('lang') || 'en').trim();
  applyCode(saved);

  // Listen for runtime language changes from the settings dropdown
  window.addEventListener('storage', (e) => {
    if (e.key === 'lang' && e.newValue) applyCode(e.newValue.trim());
  });
  // Poll as fallback (storage events don't fire on same tab)
  let _last = saved;
  setInterval(() => {
    const cur = (localStorage.getItem('lang') || 'en').trim();
    if (cur !== _last) { _last = cur; applyCode(cur); }
  }, 500);
}

export function t(key: string): string {
  return tr.dict[key] || key;
}

export function applyLang(code: string) {
  localStorage.setItem('lang', code);
  applyCode(code.trim());
}
